//! Apache httpd config generation: a main httpd.conf listening on the given
//! ports, plus one VirtualHost include per project under sites root.
use crate::error::{Error, Result};

/// Main httpd.conf that includes one file per project from `sites` dir.
pub fn generate_apache_conf(
    server_root: &str,
    sites: &[String],

    http_port: u16,
    https_port: u16,
) -> Result<String> {
    if server_root.is_empty() {
        return Err(Error::Other("server root must not be empty".into()));
    }
    let mut out = format!(
        "# generated by fidim - do not edit
ServerRoot \"{server_root}\"
Listen {http_port}
Listen {https_port}
LoadModule mpm_event_module modules/mod_mpm_event.so
LoadModule authz_core_module modules/mod_authz_core.so
LoadModule dir_module modules/mod_dir.so
LoadModule autoindex_module modules/mod_autoindex.so
LoadModule mime_module modules/mod_mime.so
LoadModule rewrite_module modules/mod_rewrite.so
LoadModule proxy_module modules/mod_proxy.so
LoadModule proxy_fcgi_module modules/mod_proxy_fcgi.so
LoadModule ssl_module modules/mod_ssl.so
LoadModule socache_shmcb_module modules/mod_socache_shmcb.so
ServerName localhost
PidFile \"{{pid}}\"

ErrorLog \"{{error_log}}\"
TypesConfig {{mime}}
DirectoryIndex index.php index.html index.htm login.php
<Directory />
    Options FollowSymLinks
    AllowOverride None
    Require all granted
</Directory>

# Default fallback / localhost dashboard
<VirtualHost *:{http_port}>
    ServerName localhost
    ServerAlias 127.0.0.1
    DocumentRoot \"{{dashboard}}\"
    DirectoryIndex index.html
    <Directory \"{{dashboard}}\">
        Options FollowSymLinks
        AllowOverride None
        Require all granted
    </Directory>
</VirtualHost>
"
    );
    let mut includes = Vec::new();
    for p in sites {
        includes.push(format!("Include \"{{sites}}/{p}.conf\""));
    }
    out.push_str(&includes.join("\n"));
    out.push('\n');
    Ok(out)
}

/// VirtualHost include: plain HTTP block and TLS block when a leaf cert file
/// exists. PHP is routed through fcgi proxy to `fpm_port`.
pub fn apache_vhost_conf(
    project: &str,
    sites_root: &str,
    fpm_port: u16,
    http_port: u16,
    https_port: u16,
    cert: Option<(&std::path::Path, &std::path::Path)>,
) -> Result<String> {
    if project.is_empty() {
        return Err(Error::Other("project name must not be empty".into()));
    }
    let docroot = format!("{sites_root}/{project}");
    let handler = format!(
        r#"    <FilesMatch "\.php$">
        SetHandler "proxy:fcgi://127.0.0.1:{fpm_port}"
    </FilesMatch>
    DirectoryIndex index.php index.html index.htm login.php
    <Directory "{docroot}">
        Options Indexes FollowSymLinks
        AllowOverride All
        Require all granted
    </Directory>
"#
    );
    let mut out = format!(
        r#"<VirtualHost *:{http_port}>
    DocumentRoot "{docroot}"
    ServerName {project}.test
{handler}    AllowEncodedSlashes On
</VirtualHost>
"#
    );
    if let Some((crt, key)) = cert {
        let crt = crt.display();
        let key = key.display();
        out.push_str(&format!(
            r#"<VirtualHost *:{https_port}>
    DocumentRoot "{docroot}"
    ServerName {project}.test
    SSLEngine on
    SSLCertificateFile "{crt}"
    SSLCertificateKeyFile "{key}"
{handler}</VirtualHost>
"#
        ));
    }
    Ok(out)
}

/// Write the generated httpd.conf and per-project includes under `etc`.
#[allow(clippy::too_many_arguments)]
pub fn regenerate(
    etc: &std::path::Path,
    server_root: &str,
    pid: &str,
    error_log: &str,
    sites_root: &str,
    projects: &[String],
    fpm_port: u16,
    http_port: u16,
    https_port: u16,
    certs_dir: Option<&str>,
) -> Result<()> {
    let conf_dir = etc.join("apache");
    let sites_dir = conf_dir.join("sites");
    let dashboard_dir = etc.join("dashboard");
    std::fs::create_dir_all(&sites_dir)?;
    std::fs::create_dir_all(&dashboard_dir)?;
    let dashboard_html = generate_dashboard_html(projects, http_port);
    std::fs::write(dashboard_dir.join("index.html"), dashboard_html)?;

    let conf = generate_apache_conf(server_root, projects, http_port, https_port)?
        .replace("{pid}", pid)
        .replace("{error_log}", error_log)
        .replace("{sites}", &sites_dir.display().to_string())
        .replace("{dashboard}", &dashboard_dir.display().to_string());
    // drop LoadModule lines for modules not shipped by this httpd build
    let mods_dir = std::path::Path::new(server_root).join("modules");
    let conf = conf
        .lines()
        .filter(|l| {
            if let Some(rest) = l.strip_prefix("LoadModule ") {
                let file = rest.split_whitespace().last().unwrap_or("");
                if file.starts_with("modules/") && !mods_dir.join(&file[8..]).exists() {
                    return false;
                }
            }
            true
        })
        .collect::<Vec<_>>()
        .join("\n");
    // minimal mime map shipped with fidim (no system deps)
    let mime_path = conf_dir.join("mime.types");
    std::fs::write(&mime_path, MINIMAL_MIME_TYPES)
        .map_err(|e| Error::Other(format!("write mime.types: {e}")))?;
    let conf = conf.replace("{mime}", &mime_path.display().to_string());
    std::fs::write(conf_dir.join("httpd.conf"), format!("{conf}\n"))?;
    // stale includes removed, then one conf per project
    if let Ok(rd) = std::fs::read_dir(&sites_dir) {
        for e in rd.flatten() {
            let _ = std::fs::remove_file(e.path());
        }
    }
    for p in projects {
        let cert = certs_dir.map(|d| {
            (
                std::path::Path::new(d).join(format!("{p}.crt")),
                std::path::Path::new(d).join(format!("{p}.key")),
            )
        });
        let cert = cert.filter(|(c, _)| c.exists());
        let cert = cert.as_ref().map(|(a, b)| (a.as_path(), b.as_path()));
        let body = apache_vhost_conf(p, sites_root, fpm_port, http_port, https_port, cert)?;
        std::fs::write(sites_dir.join(format!("{p}.conf")), body)?;
    }
    Ok(())
}

/// Generate a simple dashboard HTML displaying only the list of active projects without CSS or extra text.
pub fn generate_dashboard_html(projects: &[String], http_port: u16) -> String {
    let port_suffix = if http_port == 80 {
        String::new()
    } else {
        format!(":{http_port}")
    };
    let mut items = String::new();
    for p in projects {
        let url = format!("http://{p}.test{port_suffix}");
        items.push_str(&format!("        <li><a href=\"{url}\">{p}</a></li>\n"));
    }

    format!(
        r#"<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>Projects</title>
</head>
<body>
    <ul>
{items}    </ul>
</body>
</html>
"#
    )
}

/// Tiny static MIME table so httpd never depends on a system mime.types.
pub const MINIMAL_MIME_TYPES: &str = r#"text/html html htm
text/css css
application/javascript js mjs
application/json json
image/png png
image/gif gif
image/svg+xml svg
image/jpeg jpg jpeg
text/plain txt
application/pdf pdf
application/xml xml
"#;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn main_conf_lists_listen_ports_and_modules() {
        let c = generate_apache_conf("/root", &["blog".into()], 8080, 8443).unwrap();
        assert!(c.contains("ServerRoot \"/root\""), "ServerRoot");
        assert!(c.contains("Listen 8080"), "http port");
        assert!(c.contains("Listen 8443"), "https port");
        assert!(c.contains("LoadModule proxy_fcgi_module modules/mod_proxy_fcgi.so"));
        assert_eq!(c.matches("Include \"{sites}/").count(), 1);
    }

    #[test]
    fn vhost_has_server_name_and_fpm_proxy() {
        let c = apache_vhost_conf("blog", "/home/x/Sites", 9004, 8080, 8443, None).unwrap();
        assert!(c.contains("ServerName blog.test"), "server name");
        assert!(c.contains("DocumentRoot \"/home/x/Sites/blog\""));
        assert!(c.contains("proxy:fcgi://127.0.0.1:9004"));
        assert!(c.contains("SetHandler"), "php handler");
        assert!(!c.contains("SSLEngine"), "no cert → no ssl block");
    }

    #[test]
    fn vhost_tls_block_when_cert_given() {
        let c = apache_vhost_conf(
            "blog",
            "/Sites",
            9004,
            80,
            443,
            Some((
                std::path::Path::new("/etc/certs/blog.crt"),
                std::path::Path::new("/etc/certs/blog.key"),
            )),
        )
        .unwrap();
        assert!(!c.contains("Listen 443"));
        assert!(c.contains("SSLEngine on"));
        assert!(c.contains("SSLCertificateFile \"/etc/certs/blog.crt\""));
        assert!(c.contains("SSLCertificateKeyFile \"/etc/certs/blog.key\""));
    }

    #[test]
    fn regenerate_writes_main_conf_and_per_project_includes() {
        let t = tempfile::tempdir().unwrap();
        let etc = t.path().join("etc");
        std::fs::create_dir_all(&etc).unwrap();
        let certs = etc.join("certs");
        std::fs::create_dir_all(&certs).unwrap();
        std::fs::write(certs.join("blog.crt"), "x").unwrap();
        std::fs::write(certs.join("blog.key"), "y").unwrap();
        regenerate(
            &etc,
            "/root",
            "/pids/httpd.pid",
            "/logs/httpd.log",
            "/Sites",
            &["blog".into(), "sub.dir".into()],
            9004,
            8080,
            8443,
            Some(certs.display().to_string().as_str()),
        )
        .unwrap();
        let main = std::fs::read_to_string(etc.join("apache/httpd.conf")).unwrap();
        assert!(main.contains("PidFile \"/pids/httpd.pid\""));
        assert!(main.contains(&format!(
            "Include \"{}\"",
            etc.join("apache/sites/blog.conf").display()
        )));
        let blog = std::fs::read_to_string(etc.join("apache/sites/blog.conf")).unwrap();
        assert!(blog.contains("SSLEngine on"), "cert present → TLS block");
        let subdir = std::fs::read_to_string(etc.join("apache/sites/sub.dir.conf")).unwrap();
        assert!(!subdir.contains("SSLEngine"), "no cert → no ssl block");
    }
}
